using System;
using System.Linq;
using System.Reflection;
using System.Text.Json;
static class Program {
 static void Main() {
  var assembly = Assembly.Load(Convert.FromBase64String(""));
  var module = assembly.ManifestModule;
  int[] tokens = { 167772161, 167772162 };
  var results = tokens.Select(token => {
   try { var member = module.ResolveMember(token); return new { token, owner = member.DeclaringType.MetadataToken, definition = member.MetadataToken, error = "" }; }
   catch(Exception error) { return new { token, owner = 0, definition = 0, error = error.GetType().Name }; }
  }).ToArray();
  var types = assembly.GetTypes().Select(type => new { token = type.MetadataToken, name = type.FullName, baseType = type.BaseType?.FullName,
   fields = type.GetFields(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static | BindingFlags.Instance | BindingFlags.DeclaredOnly)
    .Select(field => new { token = field.MetadataToken, name = field.Name, owner = field.DeclaringType.MetadataToken }).ToArray() }).ToArray();
  Console.Write(JsonSerializer.Serialize(new { results, types }));
 }
}
